import React from "react";
import { Composition } from "remotion";
import { Episode } from "./Episode";
// Generated by: python3 scripts/tts.py <ep> && node scripts/build_manifest.mjs <ep>
import manifestJson from "../episodes/ep01-credit-card/render-manifest.json";
import type { Manifest } from "./schema";

const manifest = manifestJson as unknown as Manifest;

export const RemotionRoot: React.FC = () => {
  return (
    <Composition
      id="Episode"
      component={Episode as any}
      durationInFrames={manifest.totalDurationInFrames}
      fps={manifest.fps}
      width={manifest.width}
      height={manifest.height}
      defaultProps={{ manifest }}
    />
  );
};
